import os
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, send_file, abort
import hashlib
import hmac
import time

app = Flask(__name__)
app.config['UPLOAD_DIR'] = '/var/app/uploads'
app.config['SECRET_KEY'] = os.urandom(32)

class FileAccessControl:
    """Controls access to uploaded files with signed URLs."""

    def __init__(self, base_dir, secret):
        self.base_dir = os.path.realpath(base_dir)
        self.secret = secret

    def generate_token(self, username, filename, expires):
        """Generate HMAC token for file access."""
        msg = f"{username}:{filename}:{expires}".encode('utf-8')
        return hmac.new(self.secret, msg, hashlib.sha256).hexdigest()

    def verify_token(self, username, filename, expires, token):
        """Verify HMAC token."""
        # Fail closed on invalid (non-numeric) expires values instead of
        # raising an unhandled ValueError.
        try:
            expires_int = int(expires)
        except (TypeError, ValueError):
            return False
        if int(time.time()) > expires_int:
            return False
        expected = self.generate_token(username, filename, expires)
        return hmac.compare_digest(expected, token)

    def sanitize_filename(self, filename):
        """Sanitize filename to prevent path traversal.

        Uses NFC normalization to canonicalize Unicode before validation.
        This handles cases like decomposed characters that could bypass checks.
        """
        # Normalize to NFC form for consistent handling
        normalized = unicodedata.normalize('NFC', filename)

        # Block null bytes
        if '\x00' in normalized:
            return None

        # Block path traversal sequences
        if '..' in normalized:
            return None

        # Block absolute paths
        if normalized.startswith('/'):
            return None

        # Only allow safe characters in the basename
        # Allow unicode letters, digits, dots, hyphens, underscores
        basename = PurePosixPath(normalized).name
        if not basename:
            return None

        return normalized

    def resolve_path(self, filename):
        """Resolve the full path and verify it's within base_dir."""
        sanitized = self.sanitize_filename(filename)
        if sanitized is None:
            return None

        # Construct the full path
        full_path = os.path.join(self.base_dir, sanitized)

        # Resolve to real filesystem path (follows symlinks)
        real_path = os.path.realpath(full_path)

        # Final containment check against realpath of base
        if not real_path.startswith(self.base_dir + os.sep) and real_path != self.base_dir:
            return None

        return real_path


class UserFileManager:
    """Manages per-user file directories."""

    def __init__(self, acl):
        self.acl = acl

    def get_user_dir(self, username):
        """Get the user's upload directory."""
        # Sanitize username - only allow alphanumeric and underscore
        if not username.replace('_', '').isalnum():
            return None
        safe_user = username.lower()
        return os.path.realpath(os.path.join(self.acl.base_dir, 'users', safe_user))

    def get_file_path(self, username, filename):
        """Get full path to a user's file."""
        user_dir = self.get_user_dir(username)
        if user_dir is None:
            return None

        # Apply filename sanitization
        sanitized = self.acl.sanitize_filename(filename)
        if sanitized is None:
            return None

        # Build the path within user's directory
        target = os.path.join(user_dir, sanitized)

        # IMPORTANT: Resolve to real path to prevent symlink attacks
        # We use os.path.realpath here to fully resolve symlinks
        resolved = os.path.realpath(target)

        # Verify the resolved path is within the user's directory
        if not resolved.startswith(user_dir + os.sep) and resolved != user_dir:
            return None

        return resolved


acl = FileAccessControl(app.config['UPLOAD_DIR'], app.config['SECRET_KEY'])
file_mgr = UserFileManager(acl)


@app.route('/files/<username>/<path:filename>')
def download_file(username, filename):
    """Download a file from a user's directory.

    Requires valid signed token for authorization.
    """
    token = request.args.get('token', '')
    expires = request.args.get('expires', '0')

    if not acl.verify_token(username, filename, expires, token):
        abort(403)

    file_path = file_mgr.get_file_path(username, filename)
    if file_path is None:
        abort(400)

    if not os.path.isfile(file_path):
        abort(404)

    return send_file(file_path)


@app.route('/shared/<path:filename>')
def download_shared(filename):
    """Download from the shared files directory. No auth required for public files."""
    file_path = acl.resolve_path(os.path.join('shared', filename))
    if file_path is None:
        abort(400)

    if not os.path.isfile(file_path):
        abort(404)

    return send_file(file_path)


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
